const KONTEXTE = ["privat", "arbeitgeber_visolva"];
const ergebnis = [];
for (const item of $input.all()) {
  const kontext = item.json.context_id;
  const schluessel = String(item.json.idempotency_key || "");
  let grund = "";
  if (KONTEXTE.indexOf(kontext) === -1) { grund = "context_id nicht im Register"; }
  else if (!/^[a-f0-9]{64}$/.test(schluessel)) { grund = "idempotency_key ist kein SHA-256-Hex"; }
  else if (!item.json.action_id) { grund = "action_id fehlt"; }
  else if (!item.json.claimed_by) { grund = "claimed_by fehlt"; }
  if (grund) {
    throw new Error("idempotency_guard_invalid_input: " + grund);
  }
  ergebnis.push({ json: {
    context_id: kontext,
    action_id: item.json.action_id,
    idempotency_key: schluessel,
    claimed_by: item.json.claimed_by,
    ttl_minutes: item.json.ttl_minutes || 5,
    trace_id: item.json.trace_id || null
  } });
}
return ergebnis;

const ergebnis = [];
for (const item of $input.all()) {
  const erhalten = Boolean(item.json && item.json.idempotency_key);
  ergebnis.push({ json: {
    lock_granted: erhalten,
    duplicate: !erhalten,
    decision: erhalten ? "proceed" : "skip_duplicate",
    idempotency_key: item.json.idempotency_key || null
  } });
}
return ergebnis;
